import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { FilesystemWatcher } from "../integrations/filesystem-watcher/watcher.mjs";
import { resolveSecret as openclawSecret } from "../integrations/openclaw/plugin.mjs";
import { resolveSecret as piSecret } from "../integrations/pi/security.ts";

const KEY = "AGENTMEMORY_SECRET";
const LOCAL = "http://127.0.0.1:3111";

type Resolver = (url: string, explicit?: string) => string;

const resolvers: Array<[string, Resolver]> = [
  ["filesystem watcher", (url, explicit) => new FilesystemWatcher({ baseUrl: url, secret: explicit }).secret],
  ["openclaw", openclawSecret as Resolver],
  ["pi", piSecret],
];

function hasPython(): boolean {
  return spawnSync("python3", ["--version"], { stdio: "ignore" }).status === 0;
}

function hermesSecret(home: string, url: string, explicit?: string): string {
  const script = [
    "import importlib.util, sys",
    "spec = importlib.util.spec_from_file_location('hermes_plugin', sys.argv[1])",
    "mod = importlib.util.module_from_spec(spec)",
    "spec.loader.exec_module(mod)",
    "import os",
    "print(mod._usable_secret(os.environ.get('AGENTMEMORY_SECRET')) or mod._stored_secret(sys.argv[2]))",
  ].join("\n");
  const env: NodeJS.ProcessEnv = { PATH: process.env.PATH, HOME: home, USERPROFILE: home };
  if (explicit !== undefined) env[KEY] = explicit;
  const result = spawnSync("python3", ["-c", script, join(process.cwd(), "integrations", "hermes", "__init__.py"), url], {
    env,
    encoding: "utf-8",
  });
  if (result.status !== 0) throw new Error(result.stderr);
  return result.stdout.trim();
}

describe("client secret resolution", () => {
  let home: string;
  const saved = { home: process.env.HOME, profile: process.env.USERPROFILE, value: process.env[KEY] };

  beforeEach(() => {
    home = mkdtempSync(join(tmpdir(), "am-client-secret-"));
    process.env.HOME = home;
    process.env.USERPROFILE = home;
    delete process.env[KEY];
    mkdirSync(join(home, ".agentmemory"), { recursive: true });
  });

  afterEach(() => {
    process.env.HOME = saved.home;
    if (saved.profile === undefined) delete process.env.USERPROFILE;
    else process.env.USERPROFILE = saved.profile;
    if (saved.value === undefined) delete process.env[KEY];
    else process.env[KEY] = saved.value;
    rmSync(home, { recursive: true, force: true });
    vi.unstubAllGlobals();
    vi.resetModules();
  });

  function writeSecrets(envFile?: string) {
    writeFileSync(join(home, ".agentmemory", "secret"), "generated-secret\n");
    if (envFile !== undefined) writeFileSync(join(home, ".agentmemory", ".env"), envFile);
  }

  describe.each(resolvers)("%s", (_name, resolve) => {
    it("prefers the explicit secret", () => {
      writeSecrets('AGENTMEMORY_SECRET="from-env-file"\n');
      expect(resolve(LOCAL, "explicit-value")).toBe("explicit-value");
    });

    it("reads ~/.agentmemory/.env before the generated secret", () => {
      writeSecrets('AGENTMEMORY_SECRET="from-env-file"\n');
      expect(resolve(LOCAL)).toBe("from-env-file");
    });

    it("treats placeholders as unset", () => {
      writeSecrets("AGENTMEMORY_SECRET=${AGENTMEMORY_SECRET}\n");
      expect(resolve(LOCAL, "${AGENTMEMORY_SECRET}")).toBe("generated-secret");
    });

    it("reads stored files for every loopback address only", () => {
      writeSecrets();
      expect(resolve("http://127.0.0.2:3111")).toBe("generated-secret");
      expect(resolve("http://[::1]:3111")).toBe("generated-secret");
      expect(resolve("http://localhost:3111")).toBe("generated-secret");
      expect(resolve("https://memory.example.com")).toBe("");
      expect(resolve("http://localhost.example.com:3111")).toBe("");
    });
  });

  it("opencode plugin sends the secret from ~/.agentmemory/.env", async () => {
    writeSecrets('AGENTMEMORY_SECRET="from-env-file"\n');
    process.env[KEY] = "${AGENTMEMORY_SECRET}";
    const seen: Array<Record<string, string>> = [];
    vi.stubGlobal("fetch", async (_url: string, init?: RequestInit) => {
      seen.push((init?.headers || {}) as Record<string, string>);
      return new Response("{}", { status: 200, headers: { "Content-Type": "application/json" } });
    });
    vi.resetModules();
    const mod = await import("../plugin/opencode/agentmemory-capture.ts");
    const hooks = await mod.AgentmemoryCapturePlugin({ worktree: home } as never);
    await hooks.event?.({ event: { type: "session.status", properties: { sessionID: "ses_x", status: { type: "busy" } } } } as never);
    expect(seen.length).toBeGreaterThan(0);
    expect(seen[0]?.Authorization).toBe("Bearer from-env-file");
  });

  it.skipIf(!hasPython())("hermes follows the same order and keeps its loopback restriction", () => {
    writeSecrets('AGENTMEMORY_SECRET="from-env-file"\n');
    expect(hermesSecret(home, LOCAL)).toBe("from-env-file");
    expect(hermesSecret(home, LOCAL, "explicit-value")).toBe("explicit-value");
    expect(hermesSecret(home, "https://memory.example.com", "${AGENTMEMORY_SECRET}")).toBe("");
    writeFileSync(join(home, ".agentmemory", ".env"), "AGENTMEMORY_SECRET=${AGENTMEMORY_SECRET}\n");
    expect(hermesSecret(home, LOCAL)).toBe("generated-secret");
    expect(hermesSecret(home, "https://memory.example.com")).toBe("");
  });
});

import { describe, it, expect, afterAll } from "vitest";
import type { AddressInfo } from "node:net";
import { request as httpRequest } from "node:http";
import { renderViewerDocument } from "../src/viewer/document.js";
import {
  buildAllowedHosts,
  isHostAllowed,
  startViewerServer,
} from "../src/viewer/server.js";

describe("viewer document security", () => {
  it("serves a nonce-backed CSP without unsafe-inline script execution", () => {
    const rendered = renderViewerDocument();
    expect(rendered.found).toBe(true);
    if (!rendered.found) return;

    expect(rendered.csp).toContain("script-src 'nonce-");
    expect(rendered.csp).toContain("script-src-attr 'none'");
    expect(rendered.csp).toContain("img-src 'self'");
    expect(rendered.csp).not.toContain("script-src 'unsafe-inline'");
    expect(rendered.html).toContain("<script nonce=\"");
    expect(rendered.html).not.toContain("__AGENTMEMORY_VIEWER_NONCE__");
  });

  it("does not loosen img-src with bare data: URI allowance", () => {
    const rendered = renderViewerDocument();
    expect(rendered.found).toBe(true);
    if (!rendered.found) return;

    const directives = rendered.csp.split(";").map((d) => d.trim());
    const imgSrc = directives.find((d) => d.startsWith("img-src"));
    expect(imgSrc).toBeDefined();
    expect(imgSrc).toBe("img-src 'self'");
    expect(imgSrc).not.toContain("data:");

    // Favicon link in the HTML must reference the self-hosted file, not
    // an inline data: URI — that's what lets the CSP stay tight.
    expect(rendered.html).toContain('href="/favicon.svg"');
    expect(rendered.html).not.toContain("data:image/svg+xml");
  });

  it("does not contain inline DOM event handlers", () => {
    const rendered = renderViewerDocument();
    expect(rendered.found).toBe(true);
    if (!rendered.found) return;

    expect(rendered.html).not.toContain("onclick=");
    expect(rendered.html).not.toContain("onmouseover=");
    expect(rendered.html).not.toContain("onmouseout=");
  });
});

describe("viewer host allowlist (DNS rebinding defence)", () => {
  const DEFAULT_ORIGINS = [
    "http://localhost:3111",
    "http://localhost:3113",
    "http://127.0.0.1:3111",
    "http://127.0.0.1:3113",
  ];

  it("accepts loopback host:port combinations the viewer is reachable at", () => {
    const allowed = buildAllowedHosts(DEFAULT_ORIGINS, 3113);
    expect(isHostAllowed("localhost:3113", allowed)).toBe(true);
    expect(isHostAllowed("127.0.0.1:3113", allowed)).toBe(true);
    expect(isHostAllowed("[::1]:3113", allowed)).toBe(true);
  });

  it("includes the rest-port host so the same origin list works for the REST server", () => {
    const allowed = buildAllowedHosts(DEFAULT_ORIGINS, 3113);
    expect(isHostAllowed("localhost:3111", allowed)).toBe(true);
    expect(isHostAllowed("127.0.0.1:3111", allowed)).toBe(true);
  });

  it("rejects rebound attacker hostnames pointing at loopback", () => {
    const allowed = buildAllowedHosts(DEFAULT_ORIGINS, 3113);
    // Classic DNS-rebinding payload: attacker domain on the viewer port.
    expect(isHostAllowed("attacker.com:3113", allowed)).toBe(false);
    expect(isHostAllowed("evil.example:3113", allowed)).toBe(false);
    // 0.0.0.0 is a routable loopback alias on Linux but not what the
    // viewer prints; reject so an attacker can't substitute it.
    expect(isHostAllowed("0.0.0.0:3113", allowed)).toBe(false);
  });

  it("rejects bare loopback Host headers without the listening port", () => {
    const allowed = buildAllowedHosts(DEFAULT_ORIGINS, 3113);
    // Curl-style `Host: localhost` (no port) does NOT match `localhost:3113`.
    expect(isHostAllowed("localhost", allowed)).toBe(false);
    expect(isHostAllowed("127.0.0.1", allowed)).toBe(false);
  });

  it("rejects missing, empty, or non-string Host headers", () => {
    const allowed = buildAllowedHosts(DEFAULT_ORIGINS, 3113);
    expect(isHostAllowed(undefined, allowed)).toBe(false);
    expect(isHostAllowed("", allowed)).toBe(false);
    expect(isHostAllowed("   ", allowed)).toBe(false);
    // Node sets `host` to a string array only in very unusual setups;
    // treat anything non-string as forbidden.
    expect(isHostAllowed(["localhost:3113"] as unknown as string, allowed))
      .toBe(false);
  });

  it("is case-insensitive on hostname per RFC 3986 §3.2.2", () => {
    const allowed = buildAllowedHosts(DEFAULT_ORIGINS, 3113);
    expect(isHostAllowed("LOCALHOST:3113", allowed)).toBe(true);
    expect(isHostAllowed("LocalHost:3113", allowed)).toBe(true);
  });

  it("honours operator-supplied VIEWER_ALLOWED_ORIGINS on the host check", () => {
    const custom = buildAllowedHosts(
      ["http://memory.internal:8080", "http://localhost:3113"],
      3113,
    );
    expect(isHostAllowed("memory.internal:8080", custom)).toBe(true);
    expect(isHostAllowed("memory.internal", custom)).toBe(false);
    expect(isHostAllowed("attacker.com:3113", custom)).toBe(false);
  });

  it("ignores malformed origin entries instead of throwing", () => {
    const allowed = buildAllowedHosts(
      ["not-a-url", "", "http://localhost:3113"],
      3113,
    );
    expect(isHostAllowed("localhost:3113", allowed)).toBe(true);
  });
});

describe("viewer request handler DNS rebinding defence (e2e)", () => {
  const cleanups: Array<() => Promise<void>> = [];
  afterAll(async () => {
    for (const c of cleanups) await c();
  });

  async function spinUpViewer(): Promise<{ port: number }> {
    // Start on port 0 so the OS assigns a free port; passing a real port
    // exercises buildAllowedHosts() with the live listen value.
    const server = startViewerServer(0, {}, {}, undefined, 0);
    await new Promise<void>((resolve) => server.once("listening", () => resolve()));
    const addr = server.address() as AddressInfo;
    cleanups.push(
      () => new Promise<void>((resolve) => server.close(() => resolve())),
    );
    return { port: addr.port };
  }

  // Use node:http directly — the global `fetch` (undici) silently
  // overrides the Host header to the URL authority, so we cannot use it
  // to simulate a DNS-rebinding payload that lands on 127.0.0.1 while
  // carrying `Host: attacker.com`.
  function request(
    port: number,
    hostHeader: string,
    pathname = "/agentmemory/livez",
  ): Promise<{ status: number; body: string; headers: Record<string, string | string[] | undefined> }> {
    return new Promise((resolve, reject) => {
      const req = httpRequest(
        {
          host: "127.0.0.1",
          port,
          path: pathname,
          method: "GET",
          headers: { Host: hostHeader },
        },
        (res) => {
          let body = "";
          res.on("data", (chunk: Buffer) => {
            body += chunk.toString();
          });
          res.on("end", () => {
            resolve({
              status: res.statusCode ?? 0,
              body,
              headers: res.headers,
            });
          });
        },
      );
      req.on("error", reject);
      req.end();
    });
  }

  it("returns 403 on an attacker-controlled Host header (DNS rebinding payload)", async () => {
    const { port } = await spinUpViewer();
    const res = await request(port, `attacker.com:${port}`);
    expect(res.status).toBe(403);
    expect(res.body).toContain("forbidden host");
  });

  it("returns 403 even on the viewer landing page when Host is not loopback", async () => {
    const { port } = await spinUpViewer();
    const res = await request(port, `evil.example:${port}`, "/");
    expect(res.status).toBe(403);
    expect(res.body).toContain("forbidden host");
  });

  it("accepts loopback Host headers and serves the viewer HTML", async () => {
    const { port } = await spinUpViewer();
    const res = await request(port, `localhost:${port}`, "/");
    // 200 with the viewer HTML when the bundled template is resolvable,
    // or 404 when running from source without `npm run build` having
    // populated dist/viewer/. Either way it's NOT 403 — the host gate
    // passed. The CSP nonce assertion below is the load-bearing check.
    expect(res.status === 200 || res.status === 404).toBe(true);
    if (res.status === 200) {
      expect(res.body).toContain("agentmemory viewer");
    }
  });

  it("serves /favicon.svg with image/svg+xml so the tight CSP can drop data:", async () => {
    const { port } = await spinUpViewer();
    const res = await request(port, `localhost:${port}`, "/favicon.svg");
    expect(res.status).toBe(200);
    expect(res.headers["content-type"]).toBe("image/svg+xml");
    expect(res.headers["cache-control"]).toBe("public, max-age=3600");
    // SVG payload must actually be SVG, not the proxied REST error body.
    expect(res.body).toMatch(/^<svg\b/);
    expect(res.body).toContain("</svg>");
    // Sanity-check it is real SVG artwork, not an error page.
    expect(res.body).toContain('<svg');
    expect(res.body).toMatch(/<svg[^>]*viewBox="0 0 64 64"/);
  });
});

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { spawn } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { createServer, type IncomingHttpHeaders, type Server } from "node:http";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  ensureServerSecret,
  isLoopbackUrl,
  resolveClientSecret,
  secretFilePath,
} from "../src/secret-store.js";
import { resetHandleForTests, resolveHandle, setLivezProbe } from "../src/mcp/rest-proxy.js";

const KEY = "AGENTMEMORY_SECRET";

describe("stored API secret", () => {
  let home: string;
  const saved = {
    home: process.env.HOME,
    profile: process.env.USERPROFILE,
    value: process.env[KEY],
    url: process.env.AGENTMEMORY_URL,
  };

  beforeEach(() => {
    home = mkdtempSync(join(tmpdir(), "am-secret-"));
    process.env.HOME = home;
    process.env.USERPROFILE = home;
    delete process.env[KEY];
    delete process.env.AGENTMEMORY_URL;
  });

  afterEach(() => {
    process.env.HOME = saved.home;
    if (saved.profile === undefined) delete process.env.USERPROFILE;
    else process.env.USERPROFILE = saved.profile;
    if (saved.value === undefined) delete process.env[KEY];
    else process.env[KEY] = saved.value;
    if (saved.url === undefined) delete process.env.AGENTMEMORY_URL;
    else process.env.AGENTMEMORY_URL = saved.url;
    rmSync(home, { recursive: true, force: true });
  });

  it("generates a secret on first run, stores it with mode 0600 and reuses it", () => {
    const first = ensureServerSecret();
    expect(first.source).toBe("generated");
    expect(first.secret).toMatch(/^[0-9a-f]{64}$/);
    expect(secretFilePath()).toBe(join(home, ".agentmemory", "secret"));
    if (process.platform !== "win32") {
      expect(statSync(secretFilePath()).mode & 0o777).toBe(0o600);
    }
    const second = ensureServerSecret();
    expect(second).toEqual({ secret: first.secret, source: "file" });
    expect(readFileSync(secretFilePath(), "utf-8").trim()).toBe(first.secret);
  });

  it("lets an explicit secret win over the stored one", () => {
    ensureServerSecret();
    process.env[KEY] = "explicit-value";
    expect(ensureServerSecret()).toEqual({ secret: "explicit-value", source: "env" });
    expect(resolveClientSecret("http://localhost:3111")).toBe("explicit-value");
  });

  it("reads a secret set in ~/.agentmemory/.env before the generated file", () => {
    ensureServerSecret();
    writeFileSync(join(home, ".agentmemory", ".env"), 'AGENTMEMORY_SECRET="from-env-file"\n');
    expect(ensureServerSecret().secret).toBe("from-env-file");
    expect(resolveClientSecret("http://127.0.0.1:3111")).toBe("from-env-file");
  });

  it("treats unexpanded placeholders as unset", () => {
    const { secret } = ensureServerSecret();
    process.env[KEY] = "${AGENTMEMORY_SECRET}";
    expect(resolveClientSecret("http://localhost:3111")).toBe(secret);
  });

  it("only hands the stored secret to loopback servers", () => {
    const { secret } = ensureServerSecret();
    expect(resolveClientSecret("http://localhost:3111")).toBe(secret);
    expect(resolveClientSecret("http://[::1]:3111")).toBe(secret);
    expect(resolveClientSecret("https://memory.example.com")).toBe("");
    expect(isLoopbackUrl("http://127.0.0.2:3111")).toBe(true);
    expect(isLoopbackUrl("http://localhost.example.com")).toBe(false);
  });

  it("returns nothing when no secret has been generated yet", () => {
    mkdirSync(join(home, ".agentmemory"), { recursive: true });
    expect(resolveClientSecret("http://localhost:3111")).toBe("");
  });

  it("the MCP proxy sends the stored secret", async () => {
    const { secret } = ensureServerSecret();
    process.env.AGENTMEMORY_URL = "http://127.0.0.1:59999";
    const seen: Record<string, string>[] = [];
    resetHandleForTests();
    setLivezProbe(async (_url, _timeout, headers) => {
      seen.push(headers);
      return { ok: false, status: 503 };
    });
    try {
      await resolveHandle();
    } finally {
      resetHandleForTests();
    }
    expect(seen[0]?.authorization).toBe(`Bearer ${secret}`);
  });

  describe("bundled hooks", () => {
    let server: Server;
    let received: IncomingHttpHeaders[];

    beforeEach(async () => {
      received = [];
      server = createServer((req, res) => {
        received.push(req.headers);
        req.resume();
        req.on("end", () => {
          res.writeHead(200, { "Content-Type": "application/json" });
          res.end("{}");
        });
      });
      await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
    });

    afterEach(async () => {
      await new Promise((resolve) => server.close(() => resolve(null)));
    });

    function runHook(script: string, env: NodeJS.ProcessEnv): Promise<number | null> {
      return new Promise((resolve, reject) => {
        const child = spawn(process.execPath, [script], { env, stdio: ["pipe", "ignore", "ignore"] });
        child.on("error", reject);
        child.on("exit", (code) => resolve(code));
        child.stdin.end(JSON.stringify({ session_id: "ses_hook_secret", cwd: home }));
      });
    }

    it("send the stored secret without any client configuration", async () => {
      const { secret } = ensureServerSecret();
      const port = (server.address() as AddressInfo).port;
      const env: NodeJS.ProcessEnv = {
        PATH: process.env.PATH,
        HOME: home,
        USERPROFILE: home,
        AGENTMEMORY_URL: `http://127.0.0.1:${port}`,
      };
      await runHook(join(process.cwd(), "plugin", "scripts", "session-start.mjs"), env);
      expect(received.length).toBeGreaterThan(0);
      expect(received[0]?.authorization).toBe(`Bearer ${secret}`);
      expect(received[0]?.origin).toBeUndefined();
      expect(received[0]?.["content-type"]).toBe("application/json");
    });
  });
});

import { describe, it, expect, afterEach, beforeEach } from "vitest";
import { resolveEnvOrEmpty } from "../src/mcp/rest-proxy.js";

const VAR = "AGENTMEMORY_TEST_URL";

describe("resolveEnvOrEmpty — guards against literal ${VAR} placeholders", () => {
  let original: string | undefined;

  beforeEach(() => {
    original = process.env[VAR];
    delete process.env[VAR];
  });

  afterEach(() => {
    if (original === undefined) delete process.env[VAR];
    else process.env[VAR] = original;
  });

  it("returns '' when env var is unset", () => {
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("returns '' when env var is empty string", () => {
    process.env[VAR] = "";
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("returns '' when env var is literal ${VAR} placeholder", () => {
    process.env[VAR] = "${AGENTMEMORY_TEST_URL}";
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("returns '' when env var is a different literal placeholder", () => {
    process.env[VAR] = "${SOME_OTHER_VAR}";
    expect(resolveEnvOrEmpty(VAR)).toBe("");
  });

  it("preserves a real URL value", () => {
    process.env[VAR] = "https://memory.prod.example/api";
    expect(resolveEnvOrEmpty(VAR)).toBe("https://memory.prod.example/api");
  });

  it("preserves a real secret value that happens to contain a $ char", () => {
    process.env[VAR] = "secret-with-$dollar";
    expect(resolveEnvOrEmpty(VAR)).toBe("secret-with-$dollar");
  });

  it("does not treat ${ at start without matching } as placeholder", () => {
    process.env[VAR] = "${unclosed";
    expect(resolveEnvOrEmpty(VAR)).toBe("${unclosed");
  });

  it("does not treat $VAR (no braces) as placeholder", () => {
    process.env[VAR] = "$AGENTMEMORY_URL";
    expect(resolveEnvOrEmpty(VAR)).toBe("$AGENTMEMORY_URL");
  });
});

import { describe, it, expect, vi } from "vitest";
import { registerApiTriggers } from "../src/triggers/api.js";

type Handler = (req: unknown) => Promise<{ status_code: number; body: Record<string, unknown> }>;

function setup() {
  const kv = {
    get: vi.fn(async () => null),
    set: vi.fn(async (_scope: string, _key: string, value: unknown) => value),
    delete: vi.fn(async () => {}),
    list: vi.fn(async () => []),
  };
  const handlers = new Map<string, Handler>();
  const trigger = vi.fn(async (input: { function_id: string; payload: unknown }) => {
    if (input.function_id === "mem::lesson-save") return { success: true, action: "created", lesson: input.payload };
    return [];
  });
  const sdk = {
    registerFunction: (id: string, fn: Handler) => handlers.set(id, fn),
    registerTrigger: () => {},
    trigger,
    on: () => {},
  };
  registerApiTriggers(sdk as never, kv as never);
  const call = (id: string, req: { body?: unknown; query_params?: Record<string, string> }) =>
    handlers.get(id)!({ headers: {}, query_params: {}, body: {}, ...req });
  return { call, trigger };
}

describe("POST /agentmemory/lessons sourceIds", () => {
  it("stores validated sourceIds so a lesson can link to sessions and memories", async () => {
    const { call, trigger } = setup();
    const res = await call("api::lesson-save", {
      body: { content: "Snapshot RDS before upgrades", sourceIds: [" ses_infra_1 ", "mem_abc", "ses_infra_1"] },
    });
    expect(res.status_code).toBe(201);
    const payload = trigger.mock.calls[0][0].payload as Record<string, unknown>;
    expect(payload.sourceIds).toEqual(["ses_infra_1", "mem_abc"]);
    expect(payload.source).toBe("manual");
  });

  it("defaults to no sources and rejects malformed sourceIds", async () => {
    const { call, trigger } = setup();
    expect((await call("api::lesson-save", { body: { content: "No sources" } })).status_code).toBe(201);
    expect((trigger.mock.calls[0][0].payload as Record<string, unknown>).sourceIds).toEqual([]);

    for (const sourceIds of ["ses_1", [42], ["has space"], Array.from({ length: 51 }, (_, i) => `ses_${i}`)]) {
      const res = await call("api::lesson-save", { body: { content: "Bad", sourceIds } });
      expect(res.status_code).toBe(400);
    }
    expect(trigger).toHaveBeenCalledTimes(1);
  });
});

describe("GET /agentmemory/audit filters", () => {
  it("passes operation, date range and target text to the audit query", async () => {
    const { call, trigger } = setup();
    const res = await call("api::audit", {
      query_params: { operation: "forget", dateFrom: "2026-09-01", dateTo: "2026-09-30T23:59:59Z", q: "mem_", limit: "200" },
    });
