    });
    bm25.add(obs1);
    bm25.add(obs2);
    await kv.set("mem:obs:ses_1", "obs_1", obs1);
    await kv.set("mem:obs:ses_1", "obs_2", obs2);

    const hybrid = new HybridSearch(bm25, null, null, kv as never);
    const results = await hybrid.search("auth");

    expect(results.length).toBe(2);
    expect(results[0].combinedScore).toBeGreaterThanOrEqual(
      results[1].combinedScore,
    );
  });

  it("respects limit parameter", async () => {
    for (let i = 0; i < 10; i++) {
      const obs = makeObs({
        id: `obs_${i}`,
        sessionId: "ses_1",
        title: `auth feature ${i}`,
      });
      bm25.add(obs);
      await kv.set("mem:obs:ses_1", `obs_${i}`, obs);
    }

    const hybrid = new HybridSearch(bm25, null, null, kv as never);
    const results = await hybrid.search("auth", 3);
    expect(results.length).toBe(3);
  });

  it("skips observations not found in KV", async () => {
    const obs = makeObs({ id: "obs_missing", sessionId: "ses_1" });
    bm25.add(obs);

    const hybrid = new HybridSearch(bm25, null, null, kv as never);
    const results = await hybrid.search("auth");
    expect(results).toEqual([]);
  });

  it("falls back to KV.memories when an indexed entry is a saved memory", async () => {
    // mem::remember writes to KV.memories under the synthetic sessionId
    // "memory" — the BM25 index sees that synthetic sessionId, but
    // KV.observations("memory") never has anything.
    const indexable = makeObs({
      id: "mem_abc",
      sessionId: "memory",
      title: "Test memory for search",
      narrative: "Test memory for search",
      concepts: ["test", "search"],
    });
    bm25.add(indexable);

    const memory = {
      id: "mem_abc",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      type: "fact",
      title: "Test memory for search",
      content: "Test memory for search",
      concepts: ["test", "search"],
      files: [],
      sessionIds: [],
      strength: 7,
      version: 1,
      isLatest: true,
    };
    await kv.set("mem:memories", "mem_abc", memory);

    const hybrid = new HybridSearch(bm25, null, null, kv as never);
    const results = await hybrid.search("test memory search");

    expect(results.length).toBe(1);
    expect(results[0].observation.id).toBe("mem_abc");
    expect(results[0].observation.narrative).toBe("Test memory for search");
    expect(results[0].observation.concepts).toEqual(["test", "search"]);
  });
});

import { describe, it, expect, vi } from "vitest";
import { registerApiTriggers } from "../src/triggers/api.js";
import { getSearchIndex } from "../src/functions/search.js";
import { KV } from "../src/state/schema.js";

type Handler = (req: unknown) => Promise<{ status_code: number; body: Record<string, unknown> }>;

function setup(seed: Record<string, Record<string, unknown>>) {
  const store = new Map<string, Map<string, unknown>>();
  for (const [scope, rows] of Object.entries(seed)) store.set(scope, new Map(Object.entries(rows)));
  const kv = {
    get: vi.fn(async (scope: string, key: string) => store.get(scope)?.get(key) ?? null),
    set: vi.fn(async (_scope: string, _key: string, value: unknown) => value),
    delete: vi.fn(async () => {}),
    list: vi.fn(async (scope: string) => Array.from(store.get(scope)?.values() ?? [])),
  };
  const handlers = new Map<string, Handler>();
  const sdk = {
    registerFunction: (id: string, fn: Handler) => handlers.set(id, fn),
    registerTrigger: () => {},
    trigger: vi.fn(async () => ({})),
    on: () => {},
  };
  registerApiTriggers(sdk as never, kv as never);
  return (query_params: Record<string, string>) =>
    handlers.get("api::graph-node")!({ headers: {}, query_params, body: {} });
}

const node = (id: string, name: string, type: string, extra: Record<string, unknown> = {}) => ({
  id, name, type, properties: {}, sourceObservationIds: [], createdAt: "2026-09-01T00:00:00Z", ...extra,
});

describe("GET /agentmemory/graph/node", () => {
  it("returns relations with neighbors and resolves provenance to observations, sessions, projects and memories", async () => {
    const index = getSearchIndex();
    index.add({ id: "obs_gn_1", sessionId: "ses_gn", timestamp: "2026-09-01T00:00:00Z", type: "file_edit", title: "Edit checkout", facts: [], narrative: "edited", concepts: [], files: [], importance: 5 } as never);
    const call = setup({
      [KV.graphNodes]: {
        gn_a: node("gn_a", "/work/web-app/src/components/Checkout.tsx", "file", { sourceObservationIds: ["obs_gn_1"] }),
        gn_b: node("gn_b", "pricing", "concept"),
        gn_c: node("gn_c", "orders.ts", "file", { properties: { source: "graphify", sourceFile: "src/orders.ts" } }),
      },
      [KV.graphEdges]: {
        ge_1: { id: "ge_1", type: "related_to", sourceNodeId: "gn_a", targetNodeId: "gn_b", weight: 0.4, sourceObservationIds: ["obs_gn_1"], createdAt: "t" },
        ge_2: { id: "ge_2", type: "imports", sourceNodeId: "gn_c", targetNodeId: "gn_a", weight: 0.9, sourceObservationIds: [], createdAt: "t" },
        ge_3: { id: "ge_3", type: "uses", sourceNodeId: "gn_b", targetNodeId: "gn_c", weight: 0.9, sourceObservationIds: [], createdAt: "t" },
      },
      [KV.graphNodeDegree]: { gn_a: 2 },
      [KV.observations("ses_gn")]: {
        obs_gn_1: { id: "obs_gn_1", sessionId: "ses_gn", title: "Edit checkout", type: "file_edit", timestamp: "2026-09-01T00:00:00Z" },
      },
      [KV.sessions]: { ses_gn: { id: "ses_gn", project: "web-app", agentId: "coder", status: "completed", startedAt: "2026-09-01T00:00:00Z" } },
      [KV.memories]: {
        mem_1: { id: "mem_1", title: "Coupons first", type: "bug", project: "web-app", isLatest: true, concepts: [], files: [], sourceObservationIds: ["obs_gn_1"] },
        mem_2: { id: "mem_2", title: "Checkout grid", type: "pattern", isLatest: true, concepts: [], files: ["src/components/Checkout.tsx"] },
        mem_3: { id: "mem_3", title: "Old", type: "fact", isLatest: false, concepts: [], files: [], sourceObservationIds: ["obs_gn_1"] },
        mem_4: { id: "mem_4", title: "Unrelated", type: "fact", isLatest: true, concepts: ["deploy"], files: [] },
      },
    });

    const res = await call({ id: "gn_a" });
    expect(res.status_code).toBe(200);
    const body = res.body as Record<string, any>;
    expect(body.node.id).toBe("gn_a");
    expect(body.degree).toBe(2);
    expect(body.relationsTotal).toBe(2);
    expect(body.relations).toEqual([
      { edgeId: "ge_2", type: "imports", direction: "in", weight: 0.9, observationCount: 0, neighbor: { id: "gn_c", name: "orders.ts", type: "file" } },
      { edgeId: "ge_1", type: "related_to", direction: "out", weight: 0.4, observationCount: 1, neighbor: { id: "gn_b", name: "pricing", type: "concept" } },
    ]);
    expect(body.provenance.observations).toEqual([
      { id: "obs_gn_1", sessionId: "ses_gn", title: "Edit checkout", type: "file_edit", timestamp: "2026-09-01T00:00:00Z" },
    ]);
    expect(body.provenance.sessions).toEqual([
      { id: "ses_gn", project: "web-app", agentId: "coder", status: "completed", startedAt: "2026-09-01T00:00:00Z" },
    ]);
    expect(body.provenance.projects).toEqual(["web-app"]);
    expect(body.provenance.memories).toEqual([
      { id: "mem_1", title: "Coupons first", type: "bug", project: "web-app", via: "observation" },
      { id: "mem_2", title: "Checkout grid", type: "pattern", via: "name" },
    ]);
    expect(body.provenance.structural).toBeNull();

    const imported = await call({ id: "gn_c" });
    expect((imported.body as Record<string, any>).provenance.structural).toEqual({ source: "graphify", sourceFile: "src/orders.ts" });
    expect((imported.body as Record<string, any>).provenance.observations).toEqual([]);

    expect((await call({})).status_code).toBe(400);
    expect((await call({ id: "gn_missing" })).status_code).toBe(404);
    index.remove("obs_gn_1");
  });
});

import { describe, it, expect } from "vitest";
import { HybridSearch } from "../src/state/hybrid-search.js";
import { SearchIndex } from "../src/state/search-index.js";
import { VectorIndex } from "../src/state/vector-index.js";
import type { CompressedObservation } from "../src/types.js";

// Graph retrieval lists every node and edge on each search. A graph weight
// of 0 multiplied its results by zero but still paid for both traversals,
// so AGENTMEMORY_GRAPH_WEIGHT=0 saved nothing. At weight 0 the graph must
// not be read at all.

const obs: CompressedObservation = {
  id: "obs_1",
  sessionId: "ses_1",
  timestamp: new Date().toISOString(),
  type: "file_edit",
  title: "Edit auth middleware",
  subtitle: "JWT validation",
  facts: ["Added token check"],
  narrative:
    "Modified the AuthMiddleware in src/middleware/auth.ts to validate JWT tokens",
  concepts: ["authentication", "jwt"],
  files: ["src/middleware/auth.ts"],
  importance: 7,
};

function mockKV() {
  const store = new Map<string, Map<string, unknown>>();
  const listed: string[] = [];
  return {
    listed,
    get: async <T>(scope: string, key: string): Promise<T | null> =>
      (store.get(scope)?.get(key) as T) ?? null,
    set: async <T>(scope: string, key: string, data: T): Promise<T> => {
      if (!store.has(scope)) store.set(scope, new Map());
      store.get(scope)!.set(key, data);
      return data;
    },
    delete: async (scope: string, key: string): Promise<void> => {
      store.get(scope)?.delete(key);
    },
    list: async <T>(scope: string): Promise<T[]> => {
      listed.push(scope);
      const entries = store.get(scope);
      return entries ? (Array.from(entries.values()) as T[]) : [];
    },
  };
}

async function searchWith(graphWeight: number | undefined) {
  const bm25 = new SearchIndex();
  bm25.add(obs);
  const kv = mockKV();
  await kv.set("mem:obs:ses_1", "obs_1", obs);
  const hybrid =
    graphWeight === undefined
      ? new HybridSearch(bm25, null, null, kv as never)
      : new HybridSearch(bm25, null, null, kv as never, 0.4, 0.6, graphWeight);
  const results = await hybrid.search(
    "AuthMiddleware src/middleware/auth.ts JWT",
    10,
  );
  return {
    results,
    graphLists: kv.listed.filter((s) => s.startsWith("mem:graph:")),
  };
}

describe("graph weight 0 skips graph retrieval", () => {
  it("control: the default weight reads the graph", async () => {
    const { graphLists } = await searchWith(undefined);
    expect(graphLists.length).toBeGreaterThan(0);
  });

  it("weight 0 never lists a graph scope", async () => {
    const { graphLists } = await searchWith(0);
    expect(graphLists).toEqual([]);
  });

  it("weight 0 still returns the BM25 result", async () => {
    const { results } = await searchWith(0);
    expect(
      results.map((r) => r.observation?.id ?? (r as { obsId?: string }).obsId),
    ).toContain("obs_1");
  });
});

describe("graph weight 0 also skips vector-chunk graph expansion", () => {
  // Lowercase query with no entity-like tokens, so only the expansion
  // traversal (driven by the top vector hits) can read the graph.
  const embedder = {
    name: "fake",
    dimensions: 3,
    embed: async () => new Float32Array([1, 0, 0]),
    embedBatch: async (t: string[]) => t.map(() => new Float32Array([1, 0, 0])),
  };

  async function vectorSearchWith(graphWeight: number) {
    const bm25 = new SearchIndex();
    bm25.add(obs);
    const vector = new VectorIndex();
    vector.add("obs_1", "ses_1", new Float32Array([1, 0, 0]));
    const kv = mockKV();
    await kv.set("mem:obs:ses_1", "obs_1", obs);
    const hybrid = new HybridSearch(
      bm25,
      vector,
      embedder as never,
      kv as never,
      0.4,
      0.6,
      graphWeight,
    );
    await hybrid.search("validate tokens", 10);
    return kv.listed.filter((sc) => sc.startsWith("mem:graph:"));
  }

  it("control: a positive weight expands through the graph", async () => {
    expect((await vectorSearchWith(0.3)).length).toBeGreaterThan(0);
  });

  it("weight 0 does not expand through the graph", async () => {
    expect(await vectorSearchWith(0)).toEqual([]);
  });
});
